INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,0,0,'Exarch Naielle, weren\'t you overheard arguing with Hataaru earlier?',12,0,100.0,6,0,43278,84972,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,1,0,'Ahh, it\'s you. Trust me, friend, I will handle this. You may go.',12,0,100.0,0,0,43281,84620,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,2,0,'What is that? Is that Maladaar\'s work? No no, you don\'t need to do that. He is not to be trusted.',12,0,100.0,6,0,43282,84625,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,3,0,'Damn him. I thought I\'d gotten rid of Maladaar when I gave him up to the Iron Horde.',12,0,100.0,0,0,43283,84694,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,4,0,'Yes, I had Hataaru killed. And you are next.',12,0,100.0,0,0,43284,84695,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,5,0,'I am not the traitor here. It was the false prophet Velen who betrayed our people.',12,0,100.0,0,0,43285,84731,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,6,0,'I serve our true master now. The Legion whose call I once denied.',12,0,100.0,6,0,43286,84736,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,7,0,'My Lord Sargeras will scorch this pathetic world, as he has countless others.',12,0,100.0,5,0,43287,84738,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,8,0,'I have sworn the sacrament. I have taken my new name... Socrethar.',12,0,100.0,1,0,43289,84742,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,9,0,'There are others at my command. In Shattrath and Auchindoun.',12,0,100.0,0,0,43291,84759,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,10,0,'Enough! When next we meet, it will be on MY terms.',12,0,100.0,1,0,43292,84760,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,11,0,'Tell the remaining exarchs to number their days.',12,0,100.0,0,0,43293,84761,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,12,0,'You seem to know an awful lot about the tools of our enemy.',12,0,100.0,1,0,43279,84975,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (80076,13,0,'I agree. Stand down, Exarch. Enough damage has been done.',12,0,100.0,1,0,43280,84978,0,'LegionCore');
